import{_ as n,a0 as i,w as l,s as a,ao as I,I as s,x as e,a1 as r,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const E=JSON.parse('{"title":"IBM 披露了下一代 POWER10 處理器細節 | LCTT x X-CMD","titleTemplate":false,"description":"IBM 披露了下一代 POWER10 處理器細節 | LCTT (202008) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"IBM 披露了下一代 POWER10 處理器細節 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"IBM 披露了下一代 POWER10 處理器細節 | LCTT (202008) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202008/20200818 IBM details next-gen POWER10 processor","title":"IBM 披露了下一代 POWER10 處理器細節","tag":"202008","desc":""},"relativePath":"202008/20200818 IBM details next-gen POWER10 processor.md","filePath":"[post].md"}'),d={name:"202008/20200818 IBM details next-gen POWER10 processor.md"};function P(m,t,u,R,M,B){const o=i("Link");return l(),a("div",null,[t[15]||(t[15]=I('<h1 id="ibm-披露了下一代-power10-處理器細節" tabindex="-1">IBM 披露了下一代 POWER10 處理器細節 <a class="header-anchor" href="#ibm-披露了下一代-power10-處理器細節" aria-label="Permalink to “IBM 披露了下一代 POWER10 處理器細節”">​</a></h1><p><img src="https://images.idgesg.net/images/article/2020/08/power-10_06-100854570-large.jpg" alt=""></p><blockquote><p>新的 CPU 針對企業混合雲和 AI 推斷進行了優化，它採用了為 PB 級內存集羣開發的新技術。</p></blockquote><p>IBM 上週一公佈了最新的 POWER RISC CPU 系列，該系列針對企業混合雲計算和人工智能 （AI）推理進行了優化，同時還進行了其他一些改進。</p><p>Power 是上世紀 90 年代最後一款 Unix 處理器，當時 Sun Microsystems、HP、SGI 和 IBM 都有競爭性的 Unix 系統，以及與之配合的 RISC 處理器。後來，Unix 讓位給了 Linux，RISC 讓位給了 x86，但 IBM 堅持了下來。</p><p>這是 IBM 的第一款 7 納米處理器，IBM 宣稱它將在與前代 POWER9 相同的功率範圍內，將容量和處理器能效提升多達三倍。該處理器採用 15 核設計（實際上是 16 核，但其中一個沒有使用），並允許採用單芯片或雙芯片型號，因此 IBM 可以在同一外形尺寸中放入兩個處理器。每個核心最多可以有 8 個線程，每塊 CPU 最多支持 4TB 的內存。</p><p>更有趣的是一種名為 Memory Inception 的新內存集羣技術。這種形式的集羣允許系統將另一台物理服務器中的內存當作自己的內存來看待。因此，服務器不需要在每個機箱中放很多內存，而是可以在內存需求激增的時候，從鄰居那裏借到內存。或者，管理員可以在集羣的中間設置一台擁有大量內存的服務器，並在其周圍設置一些低內存服務器，這些服務器可以根據需要從大內存服務器上借用內存。</p><p>所有這些都是在 50 到 100 納秒的延遲下完成的。IBM 的傑出工程師 William Starke 在宣佈前的視頻會議上説：“這已經成為行業的聖盃了。與其在每個機器裏放很多內存，不如當我們對內存的需求激增時，我可以向鄰居借。”</p><p>POWER10 使用的是一種叫做開放內存接口（OMI）的東西，因此服務器現在可以使用 DDR4，上市後可以升級到 DDR5，它還可以使用 GPU 中使用的 GDDR6 內存。理論上，POWER10 將具備 1TB/秒的內存帶寬和 1TB/秒的 SMP 帶寬。</p><p>與 POWER9 相比，POWER10 處理器每個核心的 AES 加密引擎數量增加了四倍。這實現了多項安全增強功能。首先，這意味着在不降低性能的情況下進行全內存加密，因此入侵者無法掃描內存內容。</p><p>其次，它可以為容器提供隔離的硬件和軟件安全。這是為了解決更高密度的容器相關的行安全考慮。如果一個容器被入侵，POWER10 處理器的設計能夠防止同一虛擬機中的其他容器受到同樣的入侵影響。</p><p>最後，POWER10 提供了核心內的 AI 業務推斷。它通過片上支持用於訓練的 bfloat16 以及 AI 推斷中常用的 INT8 和 INT4 實現。這將允許事務性負載在應用中添加 AI 推斷。IBM 表示，POWER10 中的 AI 推斷是 POWER9 的 20 倍。</p><p>公告中沒有提到的是對操作系統的支持。POWER 運行 IBM 的 Unix 分支 AIX，以及 Linux。這並不太令人驚訝，因為這個消息是在 Hot Chips 上發佈的，Hot Chips 是每年在斯坦福大學舉行的年度半導體會議。Hot Chips 關注的是最新的芯片進展，所以軟件通常被排除在外。</p><p>IBM 一般會在發佈前一年左右公佈新的 POWER 處理器，所以有足夠的時間進行 AIX 的更新。</p><hr>',15)),s("p",null,[t[1]||(t[1]=e("via: ",-1)),r(o,{href:"https://www.networkworld.com/article/3571415/ibm-details-next-gen-power10-processor.html"},{default:p(()=>[...t[0]||(t[0]=[e("https://www.networkworld.com/article/3571415/ibm-details-next-gen-power10-processor.html",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=e("作者：",-1)),r(o,{href:"https://www.networkworld.com/author/Andy-Patrizio/"},{default:p(()=>[...t[2]||(t[2]=[e("Andy Patrizio",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),r(o,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[3]||(t[3]=[e("lujun9972",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),r(o,{href:"https://github.com/geekpi"},{default:p(()=>[...t[4]||(t[4]=[e("geekpi",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:p(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=e("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:p(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const f=n(d,[["render",P]]);export{E as __pageData,f as default};
